// Deterministic StyleSphere demonstration data. All results are simulated.
const customers=globalThis.HYPERPERSONAL_CUSTOMERS;
const products=globalThis.HYPERPERSONAL_PRODUCTS;
const weights={content:.55,collaborative:.25,popularity:.12,business:.08};
// Synthetic co-purchase rows are demo evidence only; the UI labels them accordingly.
const interactionEvents=[['P-01','P-02','P-05'],['P-01','P-05','P-07'],['P-02','P-05'],['P-03','P-04','P-08'],['P-03','P-08'],['P-04','P-07'],['P-01','P-07'],['P-03','P-04']];
function productVector(id){return interactionEvents.map(event=>event.includes(id)?1:0)}
function cosine(a,b){const dot=a.reduce((sum,v,i)=>sum+v*b[i],0),na=Math.sqrt(a.reduce((sum,v)=>sum+v*v,0)),nb=Math.sqrt(b.reduce((sum,v)=>sum+v*v,0));return na&&nb?dot/(na*nb):0}
function purchasedIds(c){const seeded=Array.isArray(c.interactionProductIds)?c.interactionProductIds:[],stored=readStore('events',[]),recent=state?.analytics?.recent||[],logged=[...(Array.isArray(stored)?stored:[]),...(Array.isArray(recent)?recent:[])].filter(e=>e?.customerId===c.id&&['assistant_question','storefront_product_clicked','product_clicked'].includes(e.type)).map(e=>e.details?.itemId);return[...new Set([...seeded,...logged])].filter(id=>products.some(p=>p.id===id))}
const clamp=(n,min=0,max=1)=>Math.max(min,Math.min(max,Number.isFinite(n)?n:min));
function customerScores(c){const views=clamp((Number(c.views)||0)/25,0,1),cart=clamp((Number(c.carts)||0)/4,0,1),recency=clamp(1-(Number(c.last)||0)/90),eng=clamp((Number(c.engagement)||0)/100),orders=clamp((Number(c.orders)||0)/12),discounts=clamp(Number(c.discounts)||0);const intent=clamp(.08+.20*views+.32*cart+.20*recency+.20*eng);const churn=clamp(.08+.42*(1-recency)+.22*(1-eng)+.18*(1-orders)+.10*discounts);const sensitivity=clamp(.15+.75*discounts);const historicalSpend=Math.max(0,Number.isFinite(Number(c.aov))?Number(c.aov):0)*Math.max(0,Number.isFinite(Number(c.orders))?Number(c.orders):0);return{intent,churn,sensitivity,historicalSpend,factors:{intent:[['Recent product views',.20*views],['Cart activity',.32*cart],['Recent activity',.20*recency],['Observed engagement',.20*eng]],churn:[['Time since last activity',.42*(1-recency)],['Low engagement',.22*(1-eng)],['Purchase history',.18*(1-orders)],['Discount reliance',.10*discounts]],sensitivity:[['Observed discount reliance',.75*discounts]]}}}
function purchaseHistorySize(c){return purchasedIds(c).length}
function collaborativeAvailable(c){return purchaseHistorySize(c)>0&&interactionEvents.length>=5}
const actions=['Personalized product','Complementary item','Targeted offer','Loyalty reward','Support check-in','No action'];
function contextualPrior(c,a){const s=customerScores(c),intent=s.intent,churn=s.churn,sens=s.sensitivity;const values={'Personalized product':.22+.42*intent+.12*clamp(c.engagement/100),'Complementary item':.24+.34*intent+.12*clamp(c.orders/12),'Targeted offer':.16+.28*sens+.25*churn-.08,'Loyalty reward':.20+.28*clamp(c.orders/12)+.12*(1-churn),'Support check-in':.18+.42*churn+.12*(1-intent),'No action':.28+.20*(1-intent)+.08*sens};return clamp(values[a]??.25,.05,.95)}
function initialBandit(c){return Object.fromEntries(actions.map(a=>{const mean=contextualPrior(c,a);return[a,{alpha:1+2*mean,beta:1+2*(1-mean),n:0}]}))}
function readStore(key,fallback){try{const value=localStorage.getItem(`hyperpersonal:${key}`);return value===null?fallback:JSON.parse(value)}catch{return fallback}}
function writeStore(key,value){try{localStorage.setItem(`hyperpersonal:${key}`,JSON.stringify(value))}catch{}}
async function apiRequest(url,options={}){if(typeof fetch!=='function')throw new Error('Backend unavailable.');const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})},body:options.body?JSON.stringify(options.body):undefined});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||`Request failed (${response.status}).`);return body}
const bandit=readStore('bandit',null)||{}; for(const c of customers){bandit[c.id]??={};for(const [a,prior] of Object.entries(initialBandit(c)))bandit[c.id][a]??=prior;}writeStore('bandit',bandit);
const persisted=readStore('demoState',{});customers.forEach(c=>{if(typeof persisted.consent?.[c.id]==='boolean')c.consent=persisted.consent[c.id]});
let selected=customers.find(c=>c.id===persisted.selected)||customers[0],view='overview',lastExperience=persisted.lastExperience||null,toastTimer;const state={cycle:0,feedback:persisted.feedback||0,lastAction:persisted.lastAction||null,offerRecommendedAt:persisted.offerRecommendedAt||{},generatedContent:persisted.generatedContent||null,analytics:readStore('analytics',{total:0,byType:{},recent:[]}),analyticsSource:'Browser local fallback',storageMode:'browser-local',llmConfigured:false,llmProvider:'none'};
function backendStorageLabel(){return state.storageMode==='temporary-json-file'?'Vercel temporary instance':'Local JSON file'}
function persist(){const updatedAt=Math.max(Date.now(),readStore('banditUpdatedAt',0)+1);writeStore('bandit',bandit);writeStore('banditUpdatedAt',updatedAt);writeStore('demoState',{selected:selected.id,feedback:state.feedback,lastAction:state.lastAction,lastExperience,offerRecommendedAt:state.offerRecommendedAt,generatedContent:state.generatedContent,consent:Object.fromEntries(customers.map(c=>[c.id,c.consent]))});apiRequest('/api/state',{method:'PUT',body:{bandit,updatedAt}}).then(r=>{if(r.updatedAt>=updatedAt)writeStore('banditUpdatedAt',r.updatedAt)}).catch(()=>{})}
function track(type,details={}){const events=readStore('events',[]),event={id:'evt-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),type,customerId:selected.id,details,at:new Date().toISOString()};events.push(event);if(events.length>1000)events.splice(0,events.length-1000);writeStore('events',events);const byType={};events.forEach(x=>byType[x.type]=(byType[x.type]||0)+1);state.analytics={total:events.length,byType,recent:events.slice(-8).reverse()};state.analyticsSource='Browser local fallback';apiRequest('/api/events',{method:'POST',body:event}).then(result=>{state.analytics=result.analytics;state.analyticsSource=backendStorageLabel();writeStore('analytics',state.analytics);const synced=readStore('syncedEvents',[]);synced.push(event.id);writeStore('syncedEvents',[...new Set(synced)].slice(-1500));if(view==='insights')render()}).catch(()=>{});writeStore('analytics',state.analytics)}
async function flushPendingEvents(){const events=readStore('events',[]),synced=new Set(readStore('syncedEvents',[]));for(const event of events){if(synced.has(event.id))continue;try{const result=await apiRequest('/api/events',{method:'POST',body:event});state.analytics=result.analytics;synced.add(event.id);writeStore('syncedEvents',[...synced].slice(-1500))}catch{break}}if(synced.size){state.analyticsSource=backendStorageLabel();writeStore('analytics',state.analytics)}}
async function syncBackend(){try{const [remote,analytics,health]=await Promise.all([apiRequest('/api/state'),apiRequest('/api/analytics'),apiRequest('/api/health')]);const localAt=readStore('banditUpdatedAt',0);if(remote.bandit&&Object.keys(remote.bandit).length&&remote.updatedAt>localAt){for(const c of customers)for(const action of actions)if(remote.bandit[c.id]?.[action])bandit[c.id][action]=remote.bandit[c.id][action];writeStore('bandit',bandit);writeStore('banditUpdatedAt',remote.updatedAt)}else if(!remote.bandit||!Object.keys(remote.bandit).length||localAt>remote.updatedAt)await apiRequest('/api/state',{method:'PUT',body:{bandit,updatedAt:Math.max(localAt,Date.now())}});state.analytics=analytics;state.storageMode=health.storage;state.analyticsSource=backendStorageLabel();state.llmConfigured=health.llmConfigured;state.llmProvider=health.llmProvider||'none';writeStore('analytics',analytics);await flushPendingEvents();if(view==='insights'||view==='experience'||view==='governance')render()}catch{state.llmConfigured=false;state.llmProvider='none';state.analyticsSource='Browser local fallback'}}
const dollars=n=>'$'+Number(n).toLocaleString('en-US');
function similarity(c,p){const interests=[...(c.categories||[]),...(c.style||'').toLowerCase().split(/[, ]+/),...(c.purchases||[]).map(x=>String(x).toLowerCase())];let hit=p.tags.filter(t=>interests.some(x=>x.includes(t)||t.includes(x))).length; if((c.categories||[]).includes(p.category))hit+=2;return clamp(hit/7)}
function recommend(c,n=4){if(!c.consent||!Number.isInteger(n)||n<1)return[];const maxPop=Math.max(1,...products.map(p=>p.rating*p.stock)),history=purchasedIds(c).map(productVector),useCollab=collaborativeAvailable(c),contentWeight=useCollab?weights.content:weights.content+weights.collaborative;return products.filter(p=>p.stock>0).map(p=>{const content=similarity(c,p),collab=useCollab&&history.length?history.reduce((sum,v)=>sum+cosine(v,productVector(p.id)),0)/history.length:0,pop=clamp((p.rating*p.stock)/maxPop),business=p.price<=Math.max((Number(c.aov)||0)*1.25,80)?1:.45,score=content*contentWeight+collab*(useCollab?weights.collaborative:0)+pop*weights.popularity+business*weights.business;const why=content>.35?`Preference fit: ${p.category} and ${p.tags.slice(0,2).join(' + ')}`:collab>.2?'Related to this profile’s demo purchase history':`Popularity fallback in ${p.category}`;return{...p,score,content,collab,pop,business,why,factors:{content:contentWeight,collaborative:useCollab?weights.collaborative:0,popularity:weights.popularity,business:weights.business},collaborativeAvailable:useCollab}}).sort((a,b)=>b.score-a.score).slice(0,n)}
function eligible(c){const s=customerScores(c);if(!c.consent)return['No action'];return actions.filter(a=>a==='No action'||a==='Personalized product'||a==='Complementary item'||(a==='Targeted offer'&&s.sensitivity>.55&&c.last>25&&(!state.offerRecommendedAt[c.id]||Date.now()-state.offerRecommendedAt[c.id]>=14*24*60*60*1000))||(a==='Loyalty reward'&&c.orders>=8)||(a==='Support check-in'&&s.churn>.5))}
function selectAction(c){const eligibleActions=eligible(c),ctx=bandit[c.id],scores=eligibleActions.map(a=>{const {alpha,beta}=ctx[a];return{action:a,alpha,beta,mean:alpha/(alpha+beta),contextPrior:contextualPrior(c,a),uncertainty:Math.sqrt(alpha*beta/(((alpha+beta)**2)*(alpha+beta+1)))} });const ranked=scores.map(x=>{const posteriorSample=betaSample(x.alpha,x.beta);return{...x,posteriorSample,sample:.8*posteriorSample+.2*x.contextPrior}}).sort((a,b)=>b.sample-a.sample);return{chosen:ranked[0],ranked,context:'Thompson posterior sample (80%) blended with explainable customer-context prior (20%); customer/action scoped.'}}
function betaSample(a,b){ // Johnk's beta sampler, deterministic through seeded RNG
 let x=gammaSample(a),y=gammaSample(b);return x/(x+y)}let seed=113;function rand(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646}function gammaSample(shape){if(shape<1)return gammaSample(shape+1)*Math.pow(rand(),1/shape);const d=shape-1/3,c=1/Math.sqrt(9*d);for(let i=0;i<30;i++){let x=normalSample(),v=1+c*x;if(v<=0)continue;v=v*v*v;let u=rand();if(u<1-.0331*x*x*x*x||Math.log(u)<.5*x*x+d*(1-v+Math.log(v)))return d*v}return shape}
function normalSample(){return Math.sqrt(-2*Math.log(Math.max(rand(),1e-9)))*Math.cos(2*Math.PI*rand())}
function generate(c=selected){const recs=recommend(c),decision=selectAction(c);let act=decision.chosen.action;let headline,copy;if(!c.consent){headline='Discover something new.';copy='Personalized recommendations are paused. Browse the full collection whenever you like.'}else if(c.sensitivity>.55){headline='Good style. Better value.';copy='A few thoughtful picks, with prices that make sense for you.'}else{headline=`Considered pieces. ${c.name.split(' ')[0]}-level style.`;copy=`A refined edit of new arrivals, chosen around your love of ${c.categories[0].toLowerCase()}.`};if(act==='Targeted offer')copy='A proposed 10% offer is available in this demo, based on your style and budget; no discount is issued.';if(act==='Support check-in')copy='Need a hand finding your next favorite? We can help make your search easier.';if(act==='No action'&&c.consent)copy='We’ll keep your experience quiet and useful until something truly relevant appears.';if(act==='Targeted offer')state.offerRecommendedAt[c.id]=Date.now();lastExperience={customer:c.id,recs,decision,action:act,headline,copy,time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})};persist();track('experience_generated',{action:act,itemId:recs[0]?.id||'none'});return lastExperience}
function rewardBreakdown(c,a,positive){const s=customerScores(c),response=positive?1:0,engagement=positive?.55+.45*s.intent:0,revenue=positive?clamp((Number(c.aov)||0)/200):0,discountCost=a==='Targeted offer'?.30:0,retention=(a==='Support check-in'||a==='Loyalty reward')?s.churn*.8:0,experience=positive?.75:0,raw=.35*response+.15*engagement+.15*revenue+.15*retention+.20*experience-discountCost;return{reward:clamp(raw),components:{response,engagement,revenue,discountCost,retention,experience},label:'simulated proxy; no commerce outcome is connected'}}
function outcome(success){if(!state.lastAction)return toast('Generate an experience first to create a feedback event.');const e=state.lastAction,arm=bandit[e.customer][e.action],customer=customers.find(c=>c.id===e.customer),result=rewardBreakdown(customer,e.action,success);arm.alpha+=result.reward;arm.beta+=1-result.reward;arm.n++;state.feedback++;state.lastAction=null;persist();track('bandit_feedback',{action:e.action,outcome:success?'positive':'no_response',reward:result.reward});render();toast(`Simulated ${success?'positive':'negative'} outcome recorded. ${e.action} updated.`)}
function scoreSignals(c){const s=customerScores(c),rows=[['Intent signals',s.factors.intent],['Churn signals',s.factors.churn],['Price sensitivity',s.factors.sensitivity]];return `<section class="card section-card"><h3>How the baseline scores work</h3><p class="subtitle">Transparent heuristic estimates (0–100); not trained predictions.</p>${rows.map(([label,items])=>`<div class="kv"><span>${label}</span><b>${items.map(([name,value])=>`${name}: +${Math.round(value*100)} pts`).join(' · ')}</b></div>`).join('')}<div class="demo-note">Historical spend = seeded order count × average order value. It is not a forward lifetime value forecast.</div></section>`}
function engagement(c){return Math.max(0,Math.min(100,Math.round(Number(c.engagement)||0)))}function churn(c){return customerScores(c).churn}
const pic=p=>`https://images.unsplash.com/${p.img}?auto=format&fit=crop&w=700&q=80`;
function productCard(p,explain=false,shop=false){return `<div class="card ${explain?'rec-card':'product'}"><div class="product-img" style="background-image:url('${pic(p)}')"></div><div class="product-info"><div class="row"><h4>${p.name}</h4>${explain?`<span class="match">${Math.round(p.score*100)}% match</span>`:''}</div><p>${p.brand} · ${p.category}</p><div class="row"><span class="price">${dollars(p.price)}</span>${explain?`<span class="match">★ ${p.rating}</span>`:''}</div>${explain?`<div class="explain">${p.why}. ${p.stock} in stock. Score factors: preference ${Math.round(p.factors.content*100)}%, ${p.collaborativeAvailable?'synthetic co-purchase similarity '+Math.round(p.factors.collaborative*100)+'%':'collaborative signal unavailable; weight moved to preferences'}, popularity ${Math.round(p.factors.popularity*100)}%, price/availability ${Math.round(p.factors.business*100)}%.</div>`:''}${shop?`<button class="button" data-ask-product="${p.id}" style="margin-top:10px;width:100%">Ask about this item →</button>`:''}</div></div>`}
function header(eyebrow,title,sub,right=''){return `<div class="title-row"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><div class="subtitle">${sub}</div></div>${right}</div>`}
function kpi(label,val,icon,delta,sub){return `<div class="card kpi"><div class="kpi-head">${label}<span class="kpi-icon">${icon}</span></div><div class="kpi-val">${val}</div><div class="delta">${delta}<span>${sub}</span></div></div>`}
function person(c){return `<div class="person"><span class="avatar" style="background:${c.tone}">${c.initials}</span><span>${c.name}<span class="subtext">${c.email}</span></span></div>`}
function customerPicker(){return `<select class="select" id="customerPicker">${customers.map(c=>`<option value="${c.id}" ${c.id===selected.id?'selected':''}>${c.name}</option>`).join('')}</select>`}
function chart(){let blue='0,0,0';const a=[23,25,21,31,28,38,35,44,41,52,48,63,58,68,64,78,70,86,83,99],b=[20,21,23,20,27,25,29,27,34,31,35,39,37,42,38,45,48,51,55,59],points=x=>x.map((v,i)=>`${i*34},${145-v*1.25}`).join(' ');return `<svg viewBox="0 0 646 155" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#5075f0" stop-opacity=".18"/><stop offset="1" stop-color="#5075f0" stop-opacity="0"/></linearGradient></defs>${[25,60,95,130].map(y=>`<line x1="0" y1="${y}" x2="646" y2="${y}" stroke="#eff1f4" stroke-dasharray="3 4"/>`).join('')}<polygon points="0,145 ${points(a)} 646,145" fill="url(#fill)"/><polyline points="${points(b)}" fill="none" stroke="#45c4bd" stroke-width="2"/><polyline points="${points(a)}" fill="none" stroke="#4d72ef" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function overview(){return `${header(new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase(),'Good morning, Momin 👋','Here’s what’s happening across your customer experiences today.',`<div class="row"><button class="button" data-view="customers">⌕ &nbsp;View customers</button><button class="button primary" data-generate>✳ &nbsp;Generate experience</button></div>`)}<div class="grid kpis">${kpi('DEMO PROFILES',customers.length,'♙','Synthetic','profile records')}${kpi('FEEDBACK EVENTS',state.feedback,'◉','Simulated','this browser')}${kpi('CATALOG ITEMS',products.length,'↗','Synthetic','catalog records')}${kpi('EXPERIENCES GENERATED',state.analytics?.byType?.experience_generated||0,'✳','Current session','demo state')}</div><div class="experience-banner"><div class="banner-copy"><div class="eyebrow">NEXT BEST EXPERIENCE ENGINE</div><h2>Every customer. A better next moment.</h2><p>Turn behavioral signals into experiences customers actually want.</p></div><div class="banner-actions"><button class="button" data-view="customers">Explore customers</button><button class="button primary" data-generate>✦ &nbsp;Build an experience</button></div></div><div class="grid dashboard-grid"><section class="card"><div class="card-head"><div><h3>Illustrative journey signals</h3><p>Synthetic chart for layout demonstration</p></div><span class="pill">Synthetic series</span></div><div class="card-body"><div class="row" style="justify-content:space-between"><span class="legend"><i></i> Demo series A</span><span class="legend"><i style="background:#45c4bd"></i> Demo series B</span><span class="legend">Illustrative only</span></div><div class="chart-wrap">${chart()}</div><div class="chart-labels">${['Oct 22','Oct 27','Nov 01','Nov 06','Nov 11','Nov 16','Nov 20'].map(x=>`<span>${x}</span>`).join('')}</div></div></section><section class="card"><div class="card-head"><div><h3>Demo profiles</h3><p>Two deterministic synthetic customers</p></div><button class="button ghost" data-view="customers">View all →</button></div><div class="card-body">${[['High-value loyalists',32,'#5c7af0'],['At-risk customers',24,'#df9560'],['New & exploring',21,'#48b8aa'],['Price-conscious',15,'#a27ad6'],['Other segments',8,'#bdc5d2']].map(([x,n,c])=>`<div class="bar-row"><span>${x}</span><div class="bar"><i style="width:${n*2.7}%;background:${c}"></i></div><b>${n}%</b></div>`).join('')}<div class="demo-note">Profile labels are seeded demo attributes; cohort percentages are illustrative.</div></div></section></div><div class="grid bottom-grid"><section class="card"><div class="card-head"><div><h3>Customers to know</h3><p>A closer look at individual customer journeys</p></div><button class="button ghost" data-view="customers">All customers →</button></div><div class="card-body"><table class="table"><thead><tr><th>CUSTOMER</th><th>SEGMENT</th><th>INTENT</th><th>CHURN RISK</th><th></th></tr></thead><tbody>${customers.map(c=>`<tr><td>${person(c)}</td><td><span class="pill ${customerScores(c).churn>.5?'amber':''}">${c.segment}</span></td><td>${Math.round(customerScores(c).intent*100)}%</td><td><span class="pill ${customerScores(c).churn>.5?'red':'green'}">${Math.round(churn(c)*100)}%</span></td><td><button class="button ghost" data-customer="${c.id}">View</button></td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-head"><div><h3>Intelligence activity</h3><p>Synthetic demo activity</p></div><span class="pill">LOCAL</span></div><div class="feed">${feedItems()}</div></section></div><div class="demo-note">Customer, catalog, and chart data are synthetic demo data. No live performance results are connected.</div>`}
function feedItems(){return `<div class="feed-item"><span class="feed-icon">✳</span><div class="feed-copy"><b>Experience generated</b> for ${lastExperience?customers.find(x=>x.id===lastExperience.customer).name:'None yet'}<small>${lastExperience?lastExperience.time:'No experience generated'} · Local demo state</small></div></div><div class="feed-item"><span class="feed-icon">⌁</span><div class="feed-copy"><b>Bandit state</b> · ${state.feedback} simulated feedback events<small>Stored in browser local storage</small></div></div><div class="feed-item"><span class="feed-icon">◈</span><div class="feed-copy"><b>Profile available</b> — Jordan Rivera<small>Heuristic seed profile · demo only</small></div></div><div class="feed-item"><span class="feed-icon">⌕</span><div class="feed-copy"><b>Catalog loaded</b> — ${products.length} synthetic items ready for retrieval<small>Local catalog seed · synthetic records</small></div></div>`}
function customerPage(){return `${header('CUSTOMER INTELLIGENCE','Customer 360','Understand the person behind every interaction.',`<div class="row">${customerPicker()}<button class="button primary" data-generate>✳ &nbsp;Generate personalized experience</button></div>`)}<div class="card"><div class="profile-hero">${person(selected)}<div class="profile-tags"><span class="pill">${selected.segment}</span><span class="pill green">${selected.market}</span><span class="pill">${selected.language}</span></div></div><div class="card-body"><div class="metric-row"><div><small>HISTORICAL SPEND · ESTIMATE</small><b>${dollars(customerScores(selected).historicalSpend)}</b></div><div><small>AVERAGE ORDER VALUE</small><b>${dollars(selected.aov)}</b></div><div><small>INTENT SCORE · HEURISTIC</small><b>${Math.round(customerScores(selected).intent*100)}%</b></div><div><small>CHURN RISK · ESTIMATE</small><b style="color:${churn(selected)>.5?'#d16876':'#299b75'}">${Math.round(churn(selected)*100)}%</b></div></div></div></div><div class="grid profile-columns"><div class="grid"><section class="card section-card"><h3>Behavioral intelligence</h3><div class="kv"><span>Preferred categories</span><b>${selected.categories.join(' · ')}</b></div><div class="kv"><span>Style profile</span><b>${selected.style}</b></div><div class="kv"><span>Price sensitivity</span><b>${customerScores(selected).sensitivity>.65?'High':customerScores(selected).sensitivity>.4?'Moderate':'Low'} · ${Math.round(customerScores(selected).sensitivity*100)}/100</b></div><div class="kv"><span>Engagement score</span><b>${engagement(selected)}/100</b></div><div class="kv"><span>Purchase frequency</span><b>${selected.orders} orders · ~${Math.round(180/selected.orders)} days apart</b></div><div class="kv"><span>Consent status</span><b>${selected.consent?'✓ Personalization enabled':'Opted out'}</b></div></section>${scoreSignals(selected)}<section class="card section-card"><div class="row" style="justify-content:space-between"><h3>Behavioral timeline</h3><span class="pill">Last 30 days</span></div><div class="timeline">${selected.timeline.map((t,i)=>`<div class="timeline-item"><i class="timeline-dot" style="border-color:${i===0?'#647ff0':'#b8c3d7'}"></i><div>${t[0]}<small>${t[1]}</small></div></div>`).join('')}</div></section></div><div class="grid"><section class="card section-card"><h3>Profile-based insight</h3><div class="decision-card"><h4>${customerScores(selected).sensitivity<.4?'Quality-led, highly engaged':customerScores(selected).churn>.5?'At-risk, value-driven shopper':'Emerging intent signals'}</h4><p>${customerScores(selected).sensitivity<.4?`${selected.name.split(' ')[0]} consistently chooses premium workwear and has strong order value. Protect margin; focus on exclusive new arrivals and quality-led storytelling.`:`${selected.name.split(' ')[0]} responds to value cues and has been less active recently. Lead with relevant essentials; consider a modest incentive only if intent rises.`}</p></div><div class="demo-note">Observed behavior + heuristic profile. Not a clinical or guaranteed prediction.</div></section><section class="card section-card"><div class="row" style="justify-content:space-between"><h3>Top recommendations</h3><button class="button ghost" data-view="experience">Open studio →</button></div><div class="grid" style="grid-template-columns:1fr 1fr">${recommend(selected,2).map(p=>`<div>${productCard(p,true)}</div>`).join('')}</div></section><section class="card section-card"><h3>Preference profile</h3><div class="kv"><span>Communication style</span><b>${customerScores(selected).sensitivity<.4?'Editorial, quality-led':'Friendly, value-forward'}</b></div><div class="kv"><span>Best channel</span><b>${selected.channel} · consented</b></div><div class="kv"><span>Estimate methodology</span><b>Heuristic · synthetic cohort</b></div></section></div></div>`}
function experience(){const e=lastExperience?.customer===selected.id?lastExperience:null;const recs=e?.recs||recommend(selected);const dec=e?.decision||selectAction(selected);return `${header('NEXT BEST EXPERIENCE ENGINE','Experience studio','One customer. A coordinated, explainable experience.',`<div class="row">${customerPicker()}<button class="button primary" data-generate>✦ &nbsp;${e?'Regenerate experience':'Generate experience'}</button></div>`)}<div class="grid split"><div class="grid"><section class="card section-card"><div class="row" style="justify-content:space-between"><h3>Personalized product selection</h3><span class="pill green">HYBRID RANKING</span></div><p class="subtitle" style="margin:0 0 13px">Preference ${Math.round((recs[0]?.factors.content||weights.content)*100)}% · ${recs[0]?.collaborativeAvailable?'synthetic co-purchase '+Math.round(weights.collaborative*100)+'%':'collaborative unavailable; weight shifted to preferences'} · popularity ${Math.round(weights.popularity*100)}% · business fit ${Math.round(weights.business*100)}%</p><div class="grid product-grid">${recs.map(p=>productCard(p,true)).join('')}</div></section><section class="card section-card"><h3>Personalized storefront content</h3><div class="decision-card"><span class="eyebrow">${selected.language.toUpperCase()} · ${selected.market.toUpperCase()}</span><h4 style="margin-top:8px">${e?.headline||`A considered edit, selected for ${selected.name.split(' ')[0]}.`}</h4><p>${e?.copy||`Explore ${selected.categories[0].toLowerCase()} and pieces that fit your ${customerScores(selected).sensitivity<.4?'quality-first':'value-minded'} style.`}</p><small style="color:#8390a1">Generated from profile signals with a deterministic local template. Review required before campaign publication.</small></div></section>${marketingPanel(recs)}</div><div class="grid"><section class="card section-card"><div class="row" style="justify-content:space-between"><h3>Next best action</h3><span class="pill">THOMPSON SAMPLING</span></div><div class="decision-card"><h4>${dec.chosen?.action||dec.chosen.action}</h4><p>${actionReason(selected,dec.chosen.action)} The system balances expected reward and uncertainty across eligible actions.</p><div class="decision-stat"><span>Posterior mean · simulated</span><b>${Math.round(dec.chosen.mean*100)}%</b></div><div class="decision-stat"><span>Uncertainty</span><b>±${Math.round(dec.chosen.uncertainty*100)} pts</b></div><div class="decision-stat"><span>Expected positive simulated reward</span><b>${Math.round(rewardBreakdown(selected,dec.chosen.action,true).reward*100)}%</b></div><div class="decision-stat"><span>Trade-off</span><b>${dec.chosen.action==='Targeted offer'?'Discount cost / margin':dec.chosen.action==='Support check-in'?'Customer interruption':dec.chosen.action==='No action'?'No immediate engagement':'Inventory and attention'}</b></div><div class="decision-stat"><span>Decision context</span><b>${selected.segment}</b></div></div><div class="demo-note">Beta-Bernoulli bandit estimate; simulated arm history. Human approval required for external actions.</div></section><section class="card section-card"><h3>Decision signals</h3>${[['Purchase intent',customerScores(selected).intent],['Engagement',engagement(selected)/100],['Price sensitivity',customerScores(selected).sensitivity],['Churn risk',churn(selected)]].map(x=>`<div class="kv"><span>${x[0]}</span><b>${Math.round(x[1]*100)}%</b></div>`).join('')}</section><section class="card section-card"><h3>Simulate customer feedback</h3><p class="subtitle">Record a synthetic outcome to update this customer’s action arm.</p><div class="row"><button class="button" data-outcome="success">✓ Positive outcome</button><button class="button" data-outcome="fail">× No response</button></div>${state.lastAction?`<div class="demo-note">Waiting on outcome: ${state.lastAction.action}</div>`:''}</section></div></div>`}
function actionReason(c,a){return ({'Personalized product':`Strong category match and ${Math.round(customerScores(c).intent*100)}% purchase intent support relevant discovery.`,'Complementary item':`Past purchases indicate an opportunity to complete a look without discounting.`,'Targeted offer':`Elevated price sensitivity (${Math.round(c.sensitivity*100)}%) and a ${c.last}-day gap support a modest 10% offer.`,'Loyalty reward':`${c.orders} prior orders and ${dollars(c.clv)} estimated lifetime value qualify for recognition.`,'Support check-in':`${Math.round(churn(c)*100)}% estimated churn risk suggests a helpful, low-pressure check-in.`,'No action':'Current signals do not justify interrupting this customer; preserve attention and trust.'})[a]}
function marketingPanel(recs){const saved=state.generatedContent?.customer===selected.id?state.generatedContent:null;return `<section class="card section-card"><div class="row" style="justify-content:space-between"><h3>Personalized marketing content</h3><span class="pill">${state.llmConfigured?`${state.llmProvider.toUpperCase()} AVAILABLE`:'LOCAL FALLBACK READY'}</span></div><p class="subtitle">Create a draft from the selected profile and an in-stock catalog item. Nothing is published or delivered.</p><p class="demo-note">${state.llmConfigured?`With ${state.llmProvider} configured, the synthetic first name/style, catalog facts and goal are sent to the provider.`:'Local template fallback is active; no prompt leaves this server.'}</p><form id="marketingForm" class="grid" style="grid-template-columns:1fr 1fr;gap:9px"><label class="subtitle">Channel<select required class="select" id="marketingChannel" style="display:block;width:100%;margin-top:5px"><option value="email">Email</option><option value="sms">SMS</option><option value="social">Social caption</option></select></label><label class="subtitle">Product<select required class="select" id="marketingProduct" style="display:block;width:100%;margin-top:5px">${recs.map(p=>`<option value="${p.id}">${escapeHtml(p.name)} · ${dollars(p.price)}</option>`).join('')}</select></label><label class="subtitle" style="grid-column:1/-1">Goal<input required minlength="4" maxlength="100" class="text-input" id="marketingGoal" placeholder="e.g. Introduce new workwear" style="display:block;width:100%;margin-top:5px"></label><div><button class="button primary" type="submit" ${!selected.consent||!recs.length?'disabled':''}>✦ &nbsp;Generate draft</button><span class="subtitle" style="margin-left:8px">Human approval required before use.</span></div></form>${!selected.consent?'<div class="demo-note">Enable personalization consent in Trust & governance to create a customer-specific draft.</div>':''}${saved?`<div class="decision-card" style="margin-top:12px"><div class="eyebrow">${escapeHtml(saved.provider)} · ${escapeHtml(saved.channel)} · APPROVAL REQUIRED</div><pre class="generated-copy">${escapeHtml(saved.content)}</pre></div>`:''}<div id="marketingStatus" aria-live="polite"></div></section>`}
function localMarketing(customer,product,goal,channel){const name=customer.name.split(' ')[0];const intro=`${product.name} at ${dollars(product.price)} may suit your ${customer.style.toLowerCase()} style.`;return channel==='sms'?`${name}, ${intro} Explore it whenever you’re ready.`:channel==='social'?`${product.name} · ${dollars(product.price)}. A considered pick for ${customer.style.toLowerCase()} style.`:`Subject: A thoughtful pick for you\n\nHi ${name},\n\n${intro} ${product.desc}\n\n${goal} — explore it when you have a moment.`}
async function generateMarketing(event){event.preventDefault();const status=document.getElementById('marketingStatus'),button=event.currentTarget.querySelector('[type="submit"]'),channel=document.getElementById('marketingChannel').value,goal=document.getElementById('marketingGoal').value.trim(),product=products.find(p=>p.id===document.getElementById('marketingProduct').value);if(!selected.consent){status.textContent='Personalization consent is required.';return}if(!product||!goal){status.textContent='Choose an available product and enter a goal.';return}button.disabled=true;status.textContent='Generating a grounded draft…';let result;try{result=await apiRequest('/api/content/generate',{method:'POST',body:{customer:{id:selected.id,firstName:selected.name.split(' ')[0],style:selected.style,categories:selected.categories},product:{id:product.id,name:product.name,price:product.price,stock:product.stock,description:product.desc},goal,channel}})}catch{result={content:localMarketing(selected,product,goal,channel),provider:'local-fallback'}}state.generatedContent={customer:selected.id,content:result.content,provider:result.provider,channel,productId:product.id};persist();track('marketing_generated',{itemId:product.id,channel,provider:result.provider});render();toast(`Marketing draft generated with ${result.provider}.`)}
function storefront(){let recs=lastExperience?.customer===selected.id?lastExperience.recs:recommend(selected,4),e=lastExperience?.customer===selected.id?lastExperience:null;return `${header('CUSTOMER-FACING SIMULATOR','Live storefront','See the experience through your customer’s eyes.',`<div class="row">${customerPicker()}<button class="button primary" data-generate>↻ &nbsp;Refresh experience</button></div>`)}<div class="storefront"><div class="store-nav"><div class="store-logo">STYLE<span>SPHERE</span></div><div class="store-links"><span>New arrivals</span><span>Clothing</span><span>Accessories</span><span>Our story</span></div><span style="font-size:9px;color:#8b95a3">Customer preview</span></div><div class="store-hero"><div><span class="store-personal">${selected.consent?`✦ MADE FOR ${selected.name.split(' ')[0].toUpperCase()}`:'STANDARD EXPERIENCE · PERSONALIZATION OFF'}</span><h2>${e?.headline||`${selected.consent?'Your style, in a new light.':'Discover something new.'}`}</h2><p>${e?.copy||`${selected.consent?`A personal edit, guided by your interest in ${selected.categories[0].toLowerCase()}.`:'Browse the StyleSphere collection at your own pace.'}`}</p><button class="button" id="storeBrowse" style="background:#fff;color:#26334a">Explore your edit &nbsp; →</button></div></div><section class="store-section" id="storeCollection"><div class="store-section-head"><h3>${selected.consent?'Picked for you':'Explore the collection'}</h3><span>${selected.consent?`Because you love ${selected.categories[0].toLowerCase()} →`:'Explore the collection →'}</span></div><div class="grid store-products">${recs.length?recs.map(p=>productCard(p,false,true)).join(''):`<div class="empty">Personalization is off for this profile. Product matching is paused.</div>`}</div></section><div class="demo-note" style="padding:0 20px 16px">Personalized preview for ${selected.name} · synthetic demo data</div></div>`}
function assistant(){return `${header('GROUNDED PRODUCT DISCOVERY','Shopping assistant','Ask a question. Get answers grounded in the StyleSphere catalog.',`<span class="pill">${state.llmConfigured?`${state.llmProvider.toUpperCase()} + CATALOG RETRIEVAL`:'LOCAL RETRIEVAL · GROUNDED FALLBACK'}</span>`)}<div class="card assistant"><div class="chat-panel"><div class="chat-head"><span class="kpi-icon">✧</span><div><h3>StyleSphere personal shopper</h3><small style="color:#929baa;font-size:9px">Catalog retrieval · product facts cited</small></div><span class="pill" style="margin-left:auto">LOCAL</span></div><div class="chat-messages" id="messages"><div class="message">${selected.consent?`Hi ${selected.name.split(' ')[0]}! `:'Hello! '}I’m your StyleSphere shopping assistant. I can help compare products, find items in your budget, or answer catalog questions.<div class="sources">${selected.consent?`Customer context loaded: ${selected.categories.join(', ')} · ${selected.market}`:'Personalization is off; answers use catalog data only.'}</div></div><div class="message">Try asking: “I need a versatile outfit under $100” or “What’s in stock for workwear?”</div></div><div class="chat-input"><input id="chatInput" placeholder="Ask about products, fit, budget, or availability…"><button class="button primary" id="sendChat">Send&nbsp; ↑</button></div></div><aside class="chat-aside"><h4>Relevant catalog items</h4><p>Retrieved dynamically from available product records.</p>${recommend(selected,2).map(p=>`<div class="chat-prod"><span class="swatch" style="background-image:url('${pic(p)}')"></span><span>${p.name}<small>${dollars(p.price)} · ${p.stock?'In stock':'Unavailable'}</small></span></div>`).join('')}<div class="demo-note">Answers retrieve local catalog matches first; optional ${state.llmProvider==='none'?'server-side language model':state.llmProvider} selection is used only when configured; otherwise the grounded local fallback responds.</div></aside></div>`}
function retrieve(query,c){let words=query.toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w=>w.length>2),budget=(query.match(/(?:under|below|less than|budget of)\s*\$?(\d+)/i)||[])[1];return products.filter(p=>p.stock>0).map(p=>{let hay=[p.name,p.category,p.brand,p.desc,...p.tags].join(' ').toLowerCase();let match=words.reduce((s,w)=>s+(hay.includes(w)?1:0),0);let pref=c.consent?similarity(c,p):0;if(budget&&p.price<=Number(budget))match+=2;return{...p,match:match+pref*2}}).filter(p=>p.match>.6&&(!budget||p.price<=Number(budget))).sort((a,b)=>b.match-a.match).slice(0,3)}
async function sendChat(){const input=document.getElementById('chatInput');if(!input)return;const query=input.value.trim();if(!query){input.setCustomValidity('Enter a product question.');input.reportValidity();return}input.setCustomValidity('');const box=document.getElementById('messages');box.insertAdjacentHTML('beforeend',`<div class="message user">${escapeHtml(query)}</div><div class="message" id="assistantPending">Searching in-stock catalog items…</div>`);input.value='';const found=retrieve(query,selected),documents=found.map(p=>({id:p.id,name:p.name,price:p.price,stock:p.stock,description:p.desc}));track('assistant_question',{itemId:found[0]?.id||'catalog',provider:'grounded-retrieval'});let response;try{response=await apiRequest('/api/assistant/answer',{method:'POST',body:{query,documents}})}catch{response={answer:found.length?`I found ${found.length} in-stock option(s): ${found.map(p=>`${p.name} at ${dollars(p.price)} (${p.stock} available) · ${p.id}`).join('; ')}. ${found[0].desc}`:'I could not find an in-stock product match. Try a category, style, or budget.',provider:'local-retrieval',sourceIds:found.map(p=>p.id)}}const pending=document.getElementById('assistantPending');if(pending)pending.outerHTML=`<div class="message">${escapeHtml(response.answer)}<div class="sources">${escapeHtml(response.provider)} · Sources: ${(response.sourceIds||[]).join(', ')||'catalog search'}</div></div>`;box.scrollTop=box.scrollHeight}function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function optimization(){let ctx=bandit[selected.id],dec=selectAction(selected);return `${header('CONTINUOUS OPTIMIZATION','Optimization lab','See how recorded simulated feedback changes future action selection.',`<div class="row">${customerPicker()}<button class="button" id="simRound">⟳ &nbsp;Run 5 simulated rounds</button></div>`)}<div class="grid bandit-grid"><section class="card section-card"><div class="row" style="justify-content:space-between"><h3>Action reward estimates · ${selected.name}</h3><span class="pill">BETA-BERNOULLI</span></div><p class="subtitle">Thompson sampling ranks Beta posterior draws, blended 80/20 with a transparent customer-context prior.</p><div class="action-row head"><span>ACTION</span><span>EXPECTED</span><span>α / β</span><span>OUTCOMES</span></div>${eligible(selected).map(a=>{let m=ctx[a],mean=m.alpha/(m.alpha+m.beta);return `<div class="action-row"><span class="action-name">${a}</span><span><b>${Math.round(mean*100)}%</b><div class="progress"><i style="width:${Math.round(mean*100)}%"></i></div></span><span>${m.alpha.toFixed(1)} / ${m.beta.toFixed(1)}</span><span>${m.n} recorded</span></div>`}).join('')}<div class="demo-note">Fractional reward combines simulated response, engagement proxy, revenue contribution proxy, retention value, customer experience, and offer discount cost. Inputs and outcomes are synthetic; no measured commerce impact is connected.</div></section><div class="grid"><section class="card section-card"><h3>Current selection</h3><div class="decision-card"><span class="eyebrow">SAMPLED FOR THIS DECISION</span><h4 style="margin-top:8px">${dec.chosen.action}</h4><p>${actionReason(selected,dec.chosen.action)}</p><div class="decision-stat"><span>Posterior mean</span><b>${Math.round(dec.chosen.mean*100)}%</b></div><div class="decision-stat"><span>Uncertainty</span><b>±${Math.round(dec.chosen.uncertainty*100)} pts</b></div></div><button class="button primary" style="margin-top:12px" data-generate>Generate & record pending action</button><div class="row" style="margin-top:9px"><button class="button" data-outcome="success">✓ Positive</button><button class="button" data-outcome="fail">× No response</button></div></section><section class="card section-card"><h3>Reward & safeguards</h3><div class="kv"><span>Reward signal</span><b>Simulated positive response</b></div><div class="kv"><span>Offer cap</span><b>10% maximum</b></div><div class="kv"><span>Frequency cap</span><b>1 recommendation / 14 days</b></div><div class="kv"><span>No-action arm</span><b>Always eligible</b></div><div class="kv"><span>External action approval</span><b>Required</b></div><div class="demo-note">Local demo cap tracks recommendations; no campaign is connected.</div></section></div></div><div class="demo-note">Thompson sampling ranks posterior samples from arm-specific Beta distributions. Context eligibility is customer-specific. Parameters update only when a simulated outcome is recorded.</div>`}
function sentiment(){const text=document.getElementById('sentimentInput')?.value||'';const lex={frustrated:['angry','frustrated','terrible','unacceptable','disappointed','wrong','broken','late','refund','hate','annoyed','awful','never'],positive:['love','great','happy','excellent','thanks','perfect','wonderful']};const words=text.toLowerCase().match(/[a-z']+/g)||[],neg=words.filter(w=>lex.frustrated.includes(w)).length,pos=words.filter(w=>lex.positive.includes(w)).length;let stateLabel=neg? (neg>1?'Frustrated':'Negative'):pos?'Positive':'Neutral';let act=neg?'Priority human support':pos?'Thank and reinforce':'No intervention';let reason=neg?'Negative language detected. Escalate to a human; do not send promotional content.':pos?'Positive sentiment detected. Acknowledge without over-messaging.':'No strong sentiment signals; continue with neutral, helpful language.';return `<div class="sentiment-result"><b>Sentiment: ${stateLabel}</b><br>${reason}<br><span style="color:#8c99a8">Lexicon signal · confidence ${text?Math.min(96,64+words.length*2):'—'}% · deterministic baseline</span></div>`}
function insights(){return renderAnalyticsPage()}
function governance(){return `${header('RESPONSIBLE PERSONALIZATION','Trust & governance','Customer agency and clear boundaries built into the demo.',`<span class="pill green">CONSENT-AWARE</span>`)}<div class="grid split"><div class="grid"><section class="card section-card"><h3>Customer controls</h3><div class="kv"><span>Personalization consent</span><b>${selected.consent?'Enabled for '+selected.name:'Disabled'}</b></div><div class="kv"><span>Preferred communication</span><b>${selected.channel} · inferred preference</b></div><div class="kv"><span>Offer frequency policy</span><b>14-day local offer recommendation cap</b></div><div class="kv"><span>Opt-out</span><b>Honor customer preference before activation</b></div><button class="button" id="toggleConsent" style="margin-top:12px">${selected.consent?'Simulate opt-out':'Re-enable consent'}</button></section><section class="card section-card"><h3>Human review required</h3><p class="subtitle">The demo does not send communications, issue discounts, alter prices, or publish content. Any connected production workflow must require authorized review before those actions.</p></section></div><div class="card section-card"><h3>AI transparency</h3><div class="kv"><span>Profile data</span><b>Synthetic and labeled</b></div><div class="kv"><span>Decision explanation</span><b>Signals + action rationale</b></div><div class="kv"><span>Model status</span><b>Heuristics, not trained predictions</b></div><div class="kv"><span>External LLM</span><b>${state.llmConfigured?state.llmProvider.toUpperCase()+' API configured':'Not configured · local fallback'}</b></div><div class="kv"><span>Federated learning</span><b>Not implemented</b></div><div class="kv"><span>Sentiment model</span><b>Lexicon baseline</b></div></div></div><section class="card sentiment-box" style="margin-top:14px"><div class="row" style="justify-content:space-between"><div><h3 style="margin:0 0 4px;font:700 12px Manrope">Sentiment intelligence</h3><p class="subtitle" style="margin:0 0 12px">Classify a message and choose a customer-safe next step.</p></div><span class="pill">LEXICON BASELINE</span></div><textarea id="sentimentInput" placeholder="Example: I’m frustrated that my order arrived late and the item is damaged."></textarea><div class="row" style="margin-top:9px"><button class="button primary" id="analyzeSentiment">Analyze sentiment</button><span class="subtitle">No message is sent or stored.</span></div><div id="sentimentOutput"></div></section>`}
function integrations(){return `${header('PLATFORM & BUSINESS','Integrations & plans','Modular pathways for a globally ready personalization platform.',`<span class="pill amber">DEMO · NO CONNECTIONS</span>`)}<div class="grid kpis">${kpi('STARTER','$49','◇','/ month','illustrative plan')}${kpi('GROWTH','$199','✧','/ month','illustrative plan')}${kpi('PROFESSIONAL','$599','◈','/ month','illustrative plan')}${kpi('ENTERPRISE','Custom','⌘','Regional controls','and SLA')}</div><div class="grid bottom-grid"><section class="card section-card"><h3>Integration adapters</h3>${[['Internal catalog + synthetic events','Connected · demo data','green'],['Google Retail API','Adapter planned · credentials required','amber'],['Amazon product data','Adapter planned · authorized API access','amber'],['Census Bureau API','Adapter planned · aggregate market context','amber'],['Pinterest Trends','Adapter planned · API access required','amber'],['OpenOS','Adapter planned · authorized access required','amber']].map(x=>`<div class="kv"><span>${x[0]}</span><span class="pill ${x[2]}">${x[1]}</span></div>`).join('')}<div class="demo-note">No external provider has been contacted. Add credentials via environment variables when implementing an adapter.</div></section><section class="card section-card"><h3>Global readiness</h3><div class="kv"><span>Markets</span><b>Customer-level market field</b></div><div class="kv"><span>Currency</span><b>USD demo catalog</b></div><div class="kv"><span>Language</span><b>English demo templates</b></div><div class="kv"><span>Regional content</span><b>Template-ready fields</b></div><div class="kv"><span>NRB opportunity</span><b>Potential collaboration pathway</b></div><div class="demo-note">No partnerships, market validations, or localized deployments are claimed.</div></section></div>`}
function render(){document.getElementById('pageLabel').textContent=({overview:'Overview',customers:'Customer 360',experience:'Experience studio',storefront:'Live storefront',assistant:'Shopping assistant',optimization:'Optimization lab',insights:'Insights & analytics',governance:'Trust & governance',integrations:'Integrations'})[view];const pages={overview,customers:customerPage,experience,storefront,assistant,optimization,insights,governance,integrations};document.getElementById('app').innerHTML=pages[view]();document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}
function go(v){view=v;if(v==='storefront')track('storefront_viewed',{provider:'personalized'});render();window.scrollTo(0,0)}function gen(){let e=generate();state.lastAction={customer:e.customer,action:e.action};persist();view='experience';render();toast(`Experience generated for ${selected.name}.`)}
document.addEventListener('click',e=>{let n=e.target.closest('[data-view]');if(n){go(n.dataset.view);return}let c=e.target.closest('[data-customer]');if(c){selected=customers.find(x=>x.id===c.dataset.customer);if(state.lastAction?.customer!==selected.id)state.lastAction=null;persist();go('customers');return}if(e.target.closest('[data-generate]')){gen();return}let o=e.target.closest('[data-outcome]');if(o){outcome(o.dataset.outcome==='success');return}if(e.target.id==='storeBrowse'){document.getElementById('storeCollection')?.scrollIntoView({behavior:'smooth'});return}let ask=e.target.closest('[data-ask-product]');if(ask){const item=products.find(p=>p.id===ask.dataset.askProduct);go('assistant');const input=document.getElementById('chatInput');if(input){input.value=`Tell me about ${item.name}`;sendChat()}return}if(e.target.id==='sendChat')sendChat();if(e.target.id==='analyzeSentiment'){const input=document.getElementById('sentimentInput');if(!input.value.trim()){input.setCustomValidity('Enter a customer message to analyze.');input.reportValidity();return}input.setCustomValidity('');document.getElementById('sentimentOutput').innerHTML=sentiment();track('sentiment_analyzed',{provider:'lexicon'});return}if(e.target.id==='simRound'){for(let i=0;i<5;i++){let a=selectAction(selected).chosen.action;let p=bandit[selected.id][a],positive=rand()<p.alpha/(p.alpha+p.beta),reward=rewardBreakdown(selected,a,positive).reward;p.alpha+=reward;p.beta+=1-reward;p.n++;state.feedback++}persist();track('bandit_rounds',{outcome:'5 simulated rounds'});render();toast('Five simulated feedback rounds completed.');return}if(e.target.id==='toggleConsent'){selected.consent=!selected.consent;if(!selected.consent){if(lastExperience?.customer===selected.id)lastExperience=null;if(state.lastAction?.customer===selected.id)state.lastAction=null}persist();render();toast(`Personalization ${selected.consent?'enabled':'disabled'} for ${selected.name}.`);return}if(e.target.id==='exportCsv'){const rows=[['id','name','email','market','segment','intent_heuristic','churn_heuristic'],...customers.map(c=>[c.id,c.name,c.email,c.market,c.segment,customerScores(c).intent,churn(c)])];let blob=new Blob([rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='stylesphere-synthetic-customers.csv';a.click();URL.revokeObjectURL(a.href);toast('Synthetic customer CSV exported.')}});
document.addEventListener('change',e=>{if(e.target.id==='customerPicker'){selected=customers.find(c=>c.id===e.target.value)||customers[0];if(state.lastAction?.customer!==selected.id)state.lastAction=null;persist();if(view==='storefront')track('storefront_viewed',{provider:selected.consent?'personalized':'standard'});render()}});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='chatInput')sendChat()});document.addEventListener('submit',e=>{if(e.target.id==='marketingForm')generateMarketing(e)});render();syncBackend();
